 let mode='list';function filter(){const q=$('search').value.toLocaleLowerCase(),robot=$('activity-filter').value==='robotics';let n=0,mapped=[];document.querySelectorAll('[data-place]').forEach(el=>{const matchOrg=el.dataset.org==='network'&&org.toLocaleLowerCase().includes(q);el.hidden=robot&&el.dataset.activity!=='robotics'||!!q&&!el.textContent.toLocaleLowerCase().includes(q)&&!matchOrg;if(!el.hidden){n++;if(el.dataset.coords==='true')mapped.push(el.dataset.place);}});document.querySelectorAll('[data-venue-place]').forEach(el=>el.hidden=!mapped.includes(el.dataset.venuePlace));$('result-count').textContent=t(`${n} konkret məkan · yalnız uyğun təkliflər`,`${n} конкретных места · только подходящие предложения`,`${n} concrete places · matching offers only`);$('org-discovery').hidden=!q||!org.toLocaleLowerCase().includes(q);$('venue').disabled=mapped.length===0;$('venue-results').hidden=true;$('venue').setAttribute('aria-expanded','false');}
