 let month=/^20\d{2}-(0[1-9]|1[0-2])$/.test(params.get('month'))?params.get('month'):'2026-10',day=params.get('date')&&params.get('date').startsWith(month+'-')&&Number(params.get('date').slice(8))>=1&&Number(params.get('date').slice(8))<=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate()?params.get('date'):month+'-03',view=params.get('view')==='calendar'?'calendar':'list';
